import Joi from "joi";

export const regionCreateSchema = Joi.object({
  // Optional on create (usually auto-generated by DB)
regionId: Joi.string().required().messages({
  "string.base": "Region id must be a string",
  "any.required": "Region id is required",
}),

  companyId: Joi.number().integer().required().messages({
    "number.base": "Company Id is required",
    "any.required": "Company Id is required",
  }),

  financialYearId: Joi.number().integer().required().messages({
    "number.base": "Financial Year Id is required",
    "any.required": "Financial Year Id is required",
  }),

  regionCode: Joi.string().trim().max(50).required().messages({
    "string.empty": "Region code is required",
    "any.required": "Region code is required",
  }),

  regionName: Joi.string().trim().max(150).required().messages({
    "string.empty": "Region name is required",
    "any.required": "Region name is required",
  }),

  description: Joi.string().allow(null, "").optional(),

  regionTypeId: Joi.number().integer().required().messages({
    "number.base": "Region type is required",
    "any.required": "Region type is required",
  }),

  country: Joi.string().trim().max(100).allow(null, "").optional(),

  state: Joi.string().trim().max(100).allow(null, "").optional(),

  city: Joi.string().trim().max(100).allow(null, "").optional(),

  displayOrder: Joi.number().integer().min(0).allow(null, "").optional(),

  status: Joi.string().valid("Active", "Inactive").optional(),

  createdBy: Joi.alternatives().try(Joi.number(), Joi.string()).allow(null, ""),

  createdType: Joi.string().allow(null, ""),
});

export const regionUpdateSchema = regionCreateSchema
  .fork(["financialYearId"], (schema) => schema.optional())
  .keys({
    regionId: Joi.number().integer().required().messages({
      "number.base": "Region id is required",
      "any.required": "Region id is required",
    }),
  });